+// ===== ЭКРАН ЖИВЁТ НА ОТДЕЛЬНОЙ СТРАНИЦЕ (/linux) =====
+// Экран и его настройки уехали из хаба: рабочий стол — это другой раннер, и
+// npm-hub не должен поднимать его вместе с собой. С хаба остаётся только
+// переход: оставляем ссылку в sessionStorage и уходим на /linux, страница
+// откроет её, когда стол будет готов.
+function screenGo(url, vertical) {
+  if (!url) return;
+  url = url.trim();
+  if (!/^https?:\/\//i.test(url) && !/^\//.test(url)) url = 'https://' + url;
+  try {
+    sessionStorage.setItem('screen.pending_url', url);
+    sessionStorage.setItem('screen.pending_vertical', vertical ? '1' : '0');
+  } catch {}
+  location.href = '/linux';
+}
+
+// Открыть ссылку на рабочем столе. Раньше это была вкладка внутри хаба.
+function browserOpenDesktop(url, vertical) {
+  if (!url) url = (document.getElementById('browser-url') || {}).value || '';
+  if (!url) return;
+  url = url.trim(); if (!/^https?:\/\//i.test(url)) url = 'https://' + url;
+  screenGo(url, vertical === true);
+}
+function hubBrowserGo(url) {
+  if (!url) return;
+  url = url.trim();
+  if (!/^https?:\/\//i.test(url)) url = 'https://' + url;
+  try { localStorage.setItem('hub_browser_last', url); } catch {}
+  screenGo(url, /youtube|youtu\.be/i.test(url));
+}
+// Внешний хук (мост/агент): ссылка уходит на экран.
+window.openInHubBrowser = (url) => screenGo(url, false);
+
